package org.novasos.healthysv2.maternalandchildhealth;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import org.novasos.healthysv2.TestcontainersConfiguration;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.context.TestConfiguration;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.context.annotation.Bean;import org.springframework.http.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.oauth2.jwt.*;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.web.servlet.MockMvc;import org.springframework.transaction.annotation.Transactional;
@ActiveProfiles("test")@SpringBootTest(properties={"spring.security.oauth2.resourceserver.jwt.issuer-uri=https://keycloak.example/realms/healthys","spring.security.oauth2.resourceserver.jwt.audiences=healthys-backend-apps","healthys.security.api-client-id=healthys-backend-apps","healthys.security.cors.allowed-origins=http://localhost:5173"})@AutoConfigureMockMvc@Import({TestcontainersConfiguration.class,MaternalChildApiIntegrationTests.JwtFixtures.class})@Transactional class MaternalChildApiIntegrationTests{
 static final UUID ADMIN=UUID.fromString("70000000-0000-0000-0000-000000000001");@Autowired MockMvc mvc;@Autowired JdbcTemplate jdbc;
 @Test void executesPregnancyBirthVaccinationAndGrowthWorkflow()throws Exception{Graph g=graph();String start="{\"motherPatientId\":\"%s\",\"lastMenstrualPeriod\":\"%s\",\"expectedDeliveryDate\":\"%s\"}".formatted(g.mother,LocalDate.now().minusMonths(6),LocalDate.now().plusMonths(3));UUID pregnancy=id(mvc.perform(post("/api/v1/pregnancies").header(HttpHeaders.AUTHORIZATION,"Bearer admin").contentType(MediaType.APPLICATION_JSON).content(start)).andExpect(status().isCreated()).andExpect(jsonPath("$.status").value("ACTIVE")).andReturn().getResponse().getContentAsString());mvc.perform(post("/api/v1/pregnancies/{id}/prenatal-visits",pregnancy).header(HttpHeaders.AUTHORIZATION,"Bearer admin").contentType(MediaType.APPLICATION_JSON).content("{\"professionalId\":\"%s\",\"gestationalAgeWeeks\":24,\"weight\":70,\"systolicPressure\":120,\"diastolicPressure\":80,\"fetalHeartRate\":145}".formatted(g.professional))).andExpect(status().isCreated()).andExpect(jsonPath("$.gestationalAgeWeeks").value(24));UUID risk=id(mvc.perform(post("/api/v1/pregnancies/{id}/risks",pregnancy).header(HttpHeaders.AUTHORIZATION,"Bearer admin").contentType(MediaType.APPLICATION_JSON).content("{\"riskType\":\"GESTATIONAL_DIABETES\",\"severity\":\"HIGH\"}")).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString());mvc.perform(post("/api/v1/pregnancies/{id}/risks/{risk}/resolve",pregnancy,risk).header(HttpHeaders.AUTHORIZATION,"Bearer admin")).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("RESOLVED"));String delivery="{\"organizationId\":\"%s\",\"professionalId\":\"%s\",\"deliveryDate\":\"%s\",\"deliveryType\":\"VAGINAL\",\"newborns\":[{\"childPatientId\":\"%s\",\"birthOrder\":1,\"birthWeight\":3.2,\"birthHeight\":50,\"headCircumference\":35,\"apgar1\":8,\"apgar5\":9}]}".formatted(g.organization,g.professional,Instant.now(),g.child);mvc.perform(post("/api/v1/pregnancies/{id}/delivery",pregnancy).header(HttpHeaders.AUTHORIZATION,"Bearer admin").contentType(MediaType.APPLICATION_JSON).content(delivery)).andExpect(status().isCreated()).andExpect(jsonPath("$.newborns[0].childPatientId").value(g.child.toString()));mvc.perform(post("/api/v1/child-health-records/{child}/vaccinations",g.child).header(HttpHeaders.AUTHORIZATION,"Bearer admin").contentType(MediaType.APPLICATION_JSON).content("{\"vaccineCatalogId\":\"%s\",\"doseNumber\":1,\"administeredAt\":\"%s\",\"administeredBy\":\"%s\",\"organizationId\":\"%s\",\"batchNumber\":\"LOT-1\"}".formatted(g.vaccine,Instant.now(),g.professional,g.organization))).andExpect(status().isCreated()).andExpect(jsonPath("$.vaccineCode").value("BCG"));mvc.perform(post("/api/v1/child-health-records/{child}/growth-measurements",g.child).header(HttpHeaders.AUTHORIZATION,"Bearer admin").contentType(MediaType.APPLICATION_JSON).content("{\"weight\":4.5,\"height\":55,\"headCircumference\":37,\"measuredBy\":\"%s\"}".formatted(g.professional))).andExpect(status().isCreated()).andExpect(jsonPath("$.bmi").exists());mvc.perform(get("/api/v1/pregnancies/{id}",pregnancy).header(HttpHeaders.AUTHORIZATION,"Bearer admin")).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("DELIVERED")).andExpect(jsonPath("$.prenatalVisits.length()").value(1));mvc.perform(get("/api/v1/child-health-records/{child}",g.child).header(HttpHeaders.AUTHORIZATION,"Bearer admin")).andExpect(status().isOk()).andExpect(jsonPath("$.vaccinations.length()").value(1)).andExpect(jsonPath("$.growthMeasurements.length()").value(1));}
 @Test void validatesPrenatalAndGrowthRanges()throws Exception{Graph g=graph();String start="{\"motherPatientId\":\"%s\",\"expectedDeliveryDate\":\"%s\"}".formatted(g.mother,LocalDate.now().plusMonths(5));UUID pregnancy=id(mvc.perform(post("/api/v1/pregnancies").header(HttpHeaders.AUTHORIZATION,"Bearer admin").contentType(MediaType.APPLICATION_JSON).content(start)).andReturn().getResponse().getContentAsString());mvc.perform(post("/api/v1/pregnancies/{id}/prenatal-visits",pregnancy).header(HttpHeaders.AUTHORIZATION,"Bearer admin").contentType(MediaType.APPLICATION_JSON).content("{\"gestationalAgeWeeks\":50}")).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("VALIDATION_FAILED"));}
 private Graph graph(){UUID mother=patient("Mother"),child=patient("Child"),professionalPerson=person("Doctor"),professional=UUID.randomUUID(),organization=UUID.randomUUID(),vaccine=UUID.randomUUID();jdbc.update("insert into professional.professional(id,person_id,professional_number,professional_type,status) values (?,?,?,?,?)",professional,professionalPerson,"PRO-"+professional,"DOCTOR","ACTIVE");jdbc.update("insert into organization.organization(id,organization_number,name) values (?,?,?)",organization,"ORG-"+organization,"Maternity");jdbc.update("insert into catalog.vaccine_catalog(id,code,name) values (?,?,?)",vaccine,"BCG","Tuberculosis vaccine");return new Graph(mother,child,professional,organization,vaccine);}private UUID patient(String name){UUID person=person(name),patient=UUID.randomUUID();jdbc.update("insert into patient.patient(id,person_id,patient_number) values (?,?,?)",patient,person,"PAT-"+patient);return patient;}private UUID person(String name){UUID id=UUID.randomUUID();jdbc.update("insert into identity.person(id,person_number,first_name,last_name,status) values (?,?,?,?,?)",id,"PER-"+id,name,"Doe","ACTIVE");return id;}private UUID id(String json){var m=java.util.regex.Pattern.compile("\"id\":\"([^\"]+)\"").matcher(json);if(!m.find())throw new IllegalArgumentException(json);return UUID.fromString(m.group(1));}record Graph(UUID mother,UUID child,UUID professional,UUID organization,UUID vaccine){}
 @TestConfiguration(proxyBeanMethods=false)static class JwtFixtures{@Bean JwtDecoder jwtDecoder(){return token->{Instant now=Instant.now();return Jwt.withTokenValue(token).header("alg","RS256").subject(ADMIN.toString()).issuer("https://keycloak.example/realms/healthys").audience(List.of("healthys-backend-apps")).issuedAt(now).expiresAt(now.plusSeconds(300)).claim("realm_access",Map.of("roles",List.of("PLATFORM_ADMIN"))).claim("resource_access",Map.of()).build();};}}
}
